mapper.update:
UPDATE pet_order SET order_stage='PENDING_SERVICE',confirm_mode='AUTO',confirmed_at=#{now},
  version=version+1,updated_at=#{now}
WHERE id=#{id} AND version=#{version} AND reschedule_count=#{round}
  AND order_stage='PENDING_CONFIRM' AND payment_status='PAID' AND verification_status='UNVERIFIED'
  AND confirm_deadline=#{deadline} AND confirm_deadline <= #{now}
  AND confirm_mode IS NULL AND confirmed_at IS NULL AND canceled_at IS NULL AND cancel_reason IS NULL
  AND refund_order_id IS NULL AND current_refund_application_id IS NULL AND current_aftersale_id IS NULL
  AND refunded_amount=0

mapper.select:
SELECT COUNT(*) FROM order_status_log WHERE order_id=#{orderId}
  AND event_type='AUTO_CONFIRM_ANOMALY' AND BINARY request_id=BINARY #{requestId}
  AND BINARY remark=BINARY #{remark}
